UPDATE tour.packages SET tours_id = db.tours_id, title = db.title, included = db.included, excluded = db.excluded, conditions = db.conditions, price = db.price, status = db.status, bkash_link = db.bkash_link, nagad_link = db.nagad_link FROM( VALUES
( #{item.id}, #{toursId}, #{item.title}, #{item.included}, #{item.excluded}, #{item.conditions}, #{item.price}, CAST('PUBLISHED' AS status_type), #{item.bkashLink}, #{item.nagadLink} )
) AS db ( id, tours_id, title, included, excluded, conditions, price, status, bkash_link, nagad_link ) WHERE packages.id = db.id
